(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-334":{scenario:{company:"Hạt Sen Mini Mart",supervisor:{name:"Trịnh Văn Long",role:{vi:"Quản lý Vùng Cửa hàng",en:"Area Store Manager"}},ref_code:"STK-0458",title:{vi:"Đúng nguyên nhân. Đúng tỷ lệ. Đúng sự thật.",en:"Right cause. Right rate. Right facts."},brief:{vi:"Bạn chốt báo cáo kiểm kê tháng 10 STK-0458 của cửa hàng. Tổng chênh lệch thiếu theo giá bán lẻ là 18600000 đồng; doanh thu thuần tháng 1240000000 đồng. Riêng sữa tươi thùng 48 hộp thiếu 12 thùng (4200000 đồng): camera và phiếu giao cho thấy nhà cung cấp giao 36 thùng nhưng nhân viên ký nhận 48, nhà cung cấp đã xác nhận bù. Sửa mã nguyên nhân của mặt hàng này và tỷ lệ hao hụt tháng, rồi lập báo cáo có căn cứ.",en:"You are closing the October stock count report STK-0458 for your store. Total count shortage at retail value is 18600000 VND; monthly net sales are 1240000000 VND. Fresh milk cases of 48 are 12 cases short (4200000 VND): camera footage and the delivery note show the supplier delivered 36 cases but staff signed for 48, and the supplier has confirmed a credit. Correct this item's variance reason code and the monthly shrink rate, then write an evidence-based report."},reference_title:{vi:"Biên bản kiểm kê & bảng đối soát hao hụt đã duyệt · STK-0458",en:"Approved stock count record & shrink reconciliation · STK-0458"},fields:[{id:"VAR_REASON",label:{vi:"Mã nguyên nhân chênh lệch sữa tươi",en:"Fresh milk variance reason code"},initial:"UNKNOWN-LOSS",expected:"ADMIN-ERROR",choices:["UNKNOWN-LOSS","ADMIN-ERROR","DAMAGE"],reference:"Biên bản đối chiếu nhận hàng",hint:{vi:"Chênh lệch đã có bằng chứng camera và phiếu giao thì không còn là hao hụt không rõ nguyên nhân.",en:"A variance proven by camera and delivery note is no longer an unexplained loss."}},{id:"SHRINK_PCT",label:{vi:"Tỷ lệ hao hụt tháng (%)",en:"Monthly shrink rate (%)"},initial:"1.50",expected:"1.16",reference:"Bảng đối soát hao hụt",ref_value:{vi:"Chênh lệch 18600000 đ (giá bán lẻ), gồm 4200000 đ NCC giao thiếu đã xác nhận bù; doanh thu thuần 1240000000 đ",en:"Shortage 18600000 VND at retail, incl. 4200000 VND supplier short-delivery credited; net sales 1240000000 VND"},hint:{vi:"Bản nháp chia toàn bộ chênh lệch cho doanh thu, chưa loại phần lỗi chứng từ đã được bù.",en:"The draft divides the full shortage by sales without removing the credited paperwork error."}}],sop32:{vi:"Tỷ lệ hao hụt (%) = (tổng chênh lệch kiểm kê theo giá bán lẻ - phần lỗi chứng từ đã được nhà cung cấp xác nhận bù) / doanh thu thuần tháng x 100, làm tròn 2 chữ số thập phân. Mục tiêu mô phỏng 1%.",en:"Shrink rate (%) = (total count shortage at retail - paperwork errors credited by the supplier) / monthly net sales x 100, rounded to 2 decimals. Training target 1%."},context:{label:"POS-ERP / STK-0458",metrics:[{label:{vi:"Chênh lệch kiểm kê",en:"Count shortage"},value:"18,600,000 VND"},{label:{vi:"Doanh thu thuần tháng",en:"Monthly net sales"},value:"1,240,000,000 VND"},{label:{vi:"NCC xác nhận bù",en:"Supplier credit"},value:"4,200,000 VND"},{label:{vi:"Mục tiêu hao hụt",en:"Shrink target"},value:"1.00%"}]},crisis:{vi:"Cửa hàng phó đề xuất: “Tỷ lệ vẫn trên 1%, quý này xét thưởng cả cửa hàng. Chị ghi phần thiếu còn lại thành hàng hư hỏng, rồi trừ đều vào lương 6 bạn ca tối cho xong.”",en:"The assistant store manager proposes: “The rate is still above 1% and the store bonus is reviewed this quarter. Record the remaining shortage as damage and deduct it evenly from the six evening staff's wages.”"},options:{safe:{vi:"Không ghi sai mã nguyên nhân và không tự trừ lương khi chưa xác minh; báo Quản lý vùng và bộ phận chống thất thoát, rà soát camera, quy trình nhận hàng và xử lý trách nhiệm đúng quy định.",en:"Do not falsify reason codes or deduct wages without investigation; inform the area manager and loss prevention, review cameras and receiving, and handle liability by the rules."},shortcut:{vi:"Ghi phần thiếu thành hàng hư hỏng và trừ đều lương ca tối để báo cáo đạt mục tiêu.",en:"Record the shortage as damage and split it across evening wages to hit the target."},wait:{vi:"Để nguyên bản nháp và chờ quản lý vùng tự phát hiện khi kiểm tra.",en:"Leave the draft unchanged and wait for the area manager to notice on audit."}},questions:{vi:["Vì sao chênh lệch sữa tươi phải mã ADMIN-ERROR chứ không phải UNKNOWN-LOSS hay DAMAGE? Bằng chứng nào chứng minh?","Trình bày cách tính tỷ lệ hao hụt và rủi ro pháp lý khi trừ lương tập thể không có biên bản."],en:["Why must the milk variance be ADMIN-ERROR rather than UNKNOWN-LOSS or DAMAGE? Which evidence proves it?","Explain the shrink rate calculation and the legal risk of deducting team wages without a formal record."]},hints:{vi:["Đặt bản nháp cạnh biên bản đối chiếu nhận hàng, xác định chênh lệch phát sinh ở khâu nào.","Theo SOP mục 3.2, loại phần đã được nhà cung cấp xác nhận bù trước khi chia cho doanh thu thuần.","Đọc lại SOP mục 4.2: số liệu kiểm kê phải trung thực; trách nhiệm cá nhân chỉ xử lý sau khi xác minh."],en:["Place the draft next to the receiving reconciliation and find at which step the variance arose.","Per SOP 3.2, remove the supplier-credited part before dividing by net sales.","Re-read SOP 4.2: count data must be truthful; personal liability follows only after investigation."]}},learning:{summary:{vi:"Quản lý cửa hàng bán lẻ chuỗi điều hành toàn bộ một cửa hàng: doanh số, lợi nhuận, nhân sự, tồn kho, trưng bày, dịch vụ khách hàng, an toàn và tuân thủ tiêu chuẩn của chuỗi. Nghề đòi hỏi khả năng lập lịch ca, huấn luyện đội ngũ, đọc báo cáo bán hàng, kiểm soát hao hụt và hàng cận hạn, xử lý sự cố tại chỗ và giữ trung thực tuyệt đối trong số liệu kiểm kê, tiền mặt.",en:"A chain retail store manager runs a whole store: sales, profit, staff, stock, displays, customer service, safety and compliance with chain standards. The role needs shift planning, team coaching, reading sales reports, controlling shrink and near-expiry goods, handling incidents on the spot and absolute honesty in stock count and cash figures."},responsibilities:{vi:["Lập kế hoạch doanh số, lịch ca, phân công và giám sát chất lượng phục vụ.","Kiểm soát nhận hàng, tồn kho, hạn sử dụng theo FEFO và kiểm kê định kỳ.","Triển khai trưng bày theo planogram, chương trình khuyến mại và giá niêm yết đúng.","Quản lý tiền mặt, két, đối soát POS và phòng chống thất thoát.","Bảo đảm an toàn thực phẩm, phòng cháy chữa cháy, an toàn lao động và xử lý khiếu nại."],en:["Plan sales and shifts, assign tasks and monitor service quality.","Control receiving, stock and expiry dates by FEFO and run periodic counts.","Implement planogram displays, promotions and correct shelf prices.","Manage cash, the safe, POS reconciliation and loss prevention.","Ensure food safety, fire safety, occupational safety and complaint handling."]},competencies:[{name:{vi:"Lãnh đạo đội ngũ ca",en:"Shift team leadership"},desc:{vi:"Tuyển, đào tạo, xếp ca hợp lý và giữ động lực cho nhân viên bán hàng, thu ngân.",en:"Hire, train, schedule fairly and motivate sales and cashier staff."}},{name:{vi:"Vận hành & tồn kho",en:"Operations & inventory"},desc:{vi:"Kiểm soát nhận hàng, xoay vòng hàng, hàng cận hạn và chênh lệch kiểm kê.",en:"Control receiving, stock rotation, near-expiry goods and count variances."}},{name:{vi:"Phân tích kinh doanh cửa hàng",en:"Store business analysis"},desc:{vi:"Đọc doanh số theo giờ, ngành hàng, giá trị giỏ hàng để điều chỉnh nhân sự và trưng bày.",en:"Read sales by hour, category and basket value to adjust staffing and displays."}},{name:{vi:"Trải nghiệm khách hàng",en:"Customer experience"},desc:{vi:"Giữ cửa hàng sạch, đủ hàng, thanh toán nhanh và xử lý khiếu nại tại chỗ.",en:"Keep the store clean, stocked and fast at checkout and resolve complaints on the spot."}},{name:{vi:"Liêm chính & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Báo cáo số liệu thật, xử lý kỷ luật, bồi thường đúng luật lao động.",en:"Report real figures and handle discipline and liability under labor law."}}],knowledge:{vi:["Bộ luật Lao động 2019: thời giờ làm việc, làm thêm giờ, kỷ luật, bồi thường thiệt hại; khấu trừ lương không quá 30% tiền lương thực trả hằng tháng.","Luật An toàn thực phẩm 2010: điều kiện bảo quản, truy xuất nguồn gốc và xử lý thực phẩm hết hạn.","Quản lý tồn kho bán lẻ: FIFO, FEFO, kiểm kê chu kỳ, phân loại hao hụt rõ nguyên nhân và không rõ nguyên nhân.","Planogram, quản trị không gian kệ và nguyên tắc trưng bày theo hành vi mua sắm.","Quy định hiện hành về phòng cháy, chữa cháy và cứu nạn, cứu hộ đối với cơ sở kinh doanh."],en:["Labor Code 2019: working hours, overtime, discipline and damages; wage deductions capped at 30% of the monthly net wage.","Food Safety Law 2010: storage conditions, traceability and handling expired food.","Retail inventory control: FIFO, FEFO, cycle counts and known versus unknown shrink.","Planograms, shelf space management and display principles based on shopper behavior.","Current fire prevention, firefighting and rescue rules for business premises."]},tools:["Hệ thống POS","Phần mềm ERP / quản lý kho","Máy quét mã vạch cầm tay","Hệ thống camera giám sát","Ứng dụng lập lịch ca"],kpis:{vi:["Doanh số so với kế hoạch và doanh thu trên mỗi mét vuông.","Tỷ lệ hao hụt so với doanh thu thuần.","Tỷ lệ hàng hết trên kệ và giá trị hàng hủy do hết hạn.","Điểm đánh giá của khách hàng bí mật và mức hài lòng khách hàng."],en:["Sales versus plan and sales per square meter.","Shrink as a share of net sales.","Out-of-shelf rate and value of expired write-offs.","Mystery shopper score and customer satisfaction."]},day:[{time:"06:30",vi:"Mở cửa hàng, kiểm tra an toàn, két tiền đầu ca và chất lượng hàng tươi.",en:"Open the store, check safety, the opening float and fresh produce quality."},{time:"08:30",vi:"Giám sát nhận hàng, đếm thực tế trước khi ký phiếu giao.",en:"Supervise receiving and count physically before signing delivery notes."},{time:"11:00",vi:"Kiểm tra trưng bày, giá niêm yết, hàng cận hạn và bổ sung kệ giờ cao điểm.",en:"Check displays, shelf prices, near-expiry items and peak-hour replenishment."},{time:"14:00",vi:"Huấn luyện nhân viên mới, lập lịch ca tuần và xử lý khiếu nại.",en:"Coach new staff, build the weekly rota and handle complaints."},{time:"21:30",vi:"Đối soát POS, két tiền, chênh lệch tồn và gửi báo cáo ngày.",en:"Reconcile POS, cash and stock variances and send the daily report."}],mistakes:{vi:["Ký nhận đủ hàng theo phiếu giao mà không đếm thực tế.","Gộp mọi chênh lệch vào hao hụt không rõ nguyên nhân hoặc ghi sai mã để đẹp báo cáo.","Trừ lương tập thể khi chưa có biên bản, chưa xác minh và vượt giới hạn luật cho phép."],en:["Signing for full deliveries without a physical count.","Lumping all variances into unknown shrink or using false codes to look good.","Deducting team wages without a record or investigation, or beyond legal limits."]},career:[{vi:"Nhân viên bán hàng / thu ngân",en:"Sales associate or cashier"},{vi:"Trưởng ca cửa hàng",en:"Shift leader"},{vi:"Quản lý cửa hàng",en:"Store manager"},{vi:"Quản lý vùng cửa hàng",en:"Area store manager"}],glossary:[{term:"Shrinkage",vi:"Hao hụt: phần hàng mất mát do trộm cắp, hư hỏng, lỗi chứng từ hoặc không rõ nguyên nhân.",en:"Stock loss from theft, damage, paperwork errors or unknown causes."},{term:"FEFO",vi:"Hàng hết hạn trước xuất trước, áp dụng cho hàng có hạn sử dụng.",en:"First expired, first out, used for goods with expiry dates."},{term:"Planogram",vi:"Sơ đồ trưng bày quy định vị trí, số mặt hàng và thứ tự sản phẩm trên kệ.",en:"A shelf map defining product positions, facings and order."},{term:"Cycle count",vi:"Kiểm kê chu kỳ: đếm luân phiên từng nhóm hàng thay vì đóng cửa kiểm kê toàn bộ.",en:"Counting product groups in rotation instead of a full shutdown count."},{term:"Mystery shopper",vi:"Khách hàng bí mật đánh giá dịch vụ, trưng bày theo tiêu chuẩn của chuỗi.",en:"An anonymous evaluator who rates service and displays against chain standards."}],quiz:[{q:{vi:"Chênh lệch kiểm kê 9000000 đồng, trong đó 1500000 do nhà cung cấp giao thiếu đã xác nhận bù; doanh thu thuần 600000000 đồng. Tỷ lệ hao hụt là bao nhiêu?",en:"Count shortage is 9000000 VND, of which 1500000 is a credited supplier short-delivery; net sales are 600000000 VND. What is the shrink rate?"},options:{vi:["1,50%","1,00%","0,25%","1,25%"],en:["1.50%","1.00%","0.25%","1.25%"]},answer:3,explain:{vi:"Loại phần đã được bù trước: (9000000 - 1500000) / 600000000 = 1,25%.",en:"(9000000 - 1500000) / 600000000 = 1.25%."}},{q:{vi:"Theo Bộ luật Lao động 2019, khấu trừ tiền lương hằng tháng để bồi thường thiệt hại không được vượt quá mức nào?",en:"Under the Labor Code 2019, what is the cap on monthly wage deductions for damages?"},options:{vi:["10% tiền lương","30% tiền lương thực trả hằng tháng","50% tiền lương","Toàn bộ tiền lương"],en:["10% of wages","30% of the monthly net wage","50% of wages","The whole wage"]},answer:1,explain:{vi:"Khấu trừ không quá 30% tiền lương thực trả hằng tháng và phải theo đúng trình tự xử lý bồi thường.",en:"Deductions may not exceed 30% of the monthly net wage and must follow the proper liability procedure."}},{q:{vi:"Cửa hàng phó đề nghị ghi phần thiếu thành hàng hư hỏng để đạt KPI hao hụt. Bạn làm gì?",en:"The assistant manager suggests booking the shortage as damage to hit the shrink KPI. What do you do?"},options:{vi:["Đồng ý vì giúp cả cửa hàng có thưởng","Ghi một nửa là hư hỏng cho cân bằng","Từ chối, giữ mã đúng, báo quản lý vùng và chống thất thoát để điều tra","Xóa phiếu kiểm kê và đếm lại đến khi khớp"],en:["Agree so the store gets its bonus","Book half as damage to balance it","Refuse, keep true codes and report to the area manager and loss prevention","Delete the count sheet and recount until it matches"]},answer:2,explain:{vi:"Ghi sai mã che giấu nguyên nhân thật, làm chuỗi không xử lý được rủi ro và là hành vi gian lận số liệu.",en:"False codes hide the real cause, stop the chain from fixing risk and are data fraud."}},{q:{vi:"FEFO trong quản lý hàng có hạn sử dụng nghĩa là gì?",en:"What does FEFO mean for dated goods?"},options:{vi:["Hàng hết hạn trước xuất trước","Hàng nhập trước xuất trước","Hàng nhập sau xuất trước","Hàng giá cao xuất trước"],en:["First expired, first out","First in, first out","Last in, first out","Highest price out first"]},answer:0,explain:{vi:"FEFO ưu tiên bán hàng có hạn dùng gần nhất, giảm hàng hủy và rủi ro an toàn thực phẩm.",en:"FEFO sells the nearest expiry first, cutting write-offs and food safety risk."}}],tools_en:["POS system","ERP / inventory management software","Handheld barcode scanners","CCTV surveillance system","Shift scheduling app"]}}})})(window.KKR);
